<?php require __DIR__.'/app/bootstrap.php';$s=db()->prepare('SELECT * FROM articles WHERE slug=? AND is_published=1');$s->execute([$_GET['slug']??'']);$a=$s->fetch();if(!$a){http_response_code(404);head('Story not found');nav();echo '<section class="page-hero"><h1>Story not found.</h1><a href="/journal">Back to the journal</a></section>';end_page();exit;}head($a['title'],$a['excerpt'],$a['image_url']);nav(); ?>
<main class="article-page"><header class="article-heading"><div class="section-index"><?=e(strtoupper($a['category']))?> · <?=date('F j, Y',strtotime($a['published_at']))?></div><h1><?=e($a['title'])?></h1><p><?=e($a['excerpt'])?></p></header><img class="article-cover" src="<?=e(image_url($a['image_url']))?>" alt="<?=e($a['title'])?>"><article class="article-body"><?php foreach(explode("\n\n",$a['body']) as $para) echo '<p>'.e($para).'</p>'; ?><a class="text-link" href="/journal">← Back to all stories</a></article></main><?php end_page(); ?>
